// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

import {IBridgeAdapter} from "../interfaces/IBridgeAdapter.sol";
import {IInboxCallback} from "../interfaces/IInboxCallback.sol";

/// @title BridgeAdapter
/// @author Agustin Aguilar
/// @notice Base contract for adapters that bridge assets from a PDA inbox
abstract contract BridgeAdapter is IBridgeAdapter {
  struct BridgeRouteTarget {
    bool supported;
    address tokenOut;
  }

  error TokenApprovalFailed(address _token);

  mapping(bytes32 routeKey => BridgeRouteTarget target) private bridgeRouteTargets;

  function supportsBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId)
    public
    view
    virtual
    returns (bool _supported)
  {
    BridgeRouteTarget storage target = bridgeRouteTargets[_bridgeRouteKey(_tokenIn, _dstChainId)];
    return target.supported && target.tokenOut == _tokenOut;
  }

  function _executeInboxTransaction(address _inbox, address _target, uint256 _value, bytes memory _data)
    internal
    returns (bytes memory _result)
  {
    return IInboxCallback(msg.sender).executeBridgeInboxTransaction(_inbox, _target, _value, _data);
  }

  function _addressToBytes32(address _addr) internal pure returns (bytes32) {
    return bytes32(uint256(uint160(_addr)));
  }

  function _inboxAssetBalance(address _inbox, address _token) internal view returns (uint256) {
    if (_token == address(0)) {
      return _inbox.balance;
    }

    return IERC20(_token).balanceOf(_inbox);
  }

  function _resolveAmountIn(uint256 _amountIn, uint256 _balance) internal pure returns (uint256) {
    return _amountIn == 0 ? _balance : _amountIn;
  }

  function _setInboxTokenApproval(address _inbox, address _token, address _spender, uint256 _amount) internal {
    bytes memory result =
      _executeInboxTransaction(_inbox, _token, 0, abi.encodeCall(IERC20.approve, (_spender, _amount)));
    if (result.length != 0 && !abi.decode(result, (bool))) {
      revert TokenApprovalFailed(_token);
    }
  }

  function _setBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId) internal {
    bridgeRouteTargets[_bridgeRouteKey(_tokenIn, _dstChainId)] =
      BridgeRouteTarget({supported: true, tokenOut: _tokenOut});
  }

  function _clearBridgeRoute(address _tokenIn, uint256 _dstChainId) internal {
    delete bridgeRouteTargets[_bridgeRouteKey(_tokenIn, _dstChainId)];
  }

  function _bridgeRouteKey(address _tokenIn, uint256 _dstChainId) private pure returns (bytes32) {
    return keccak256(abi.encode(_tokenIn, _dstChainId));
  }
}

