// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

import {BridgeAdapter} from "./BridgeAdapter.sol";
import {BridgeExecution, BridgeFee, BridgeQuote} from "../interfaces/IBridgeAdapter.sol";
import {ICctpTokenMessengerV2, ICctpTokenMinterV2} from "../interfaces/ICctpTokenMessengerV2.sol";
import {SolanaPda} from "../libraries/SolanaPda.sol";

/// @title CctpAdapter
/// @author Agustin Aguilar
/// @notice Bridge adapter for CCTP burns from an inbox
contract CctpAdapter is BridgeAdapter, Ownable {
  struct SolanaAta {
    bytes32 mint;
    bytes32 tokenProgram;
    bytes32 associatedTokenProgram;
  }

  /// @dev A destination is unset when `tokenOut == 0`. When set, `solanaAta.mint == 0` is a raw
  ///      recipient passthrough; a non-zero `solanaAta` derives the recipient's associated token
  ///      account on-chain (see `_cctpMintRecipient`).
  struct Destination {
    address tokenOut;
    uint32 cctpDomain;
    uint32 minFinalityThreshold;
    SolanaAta solanaAta;
  }

  /// @dev Circle's CCTP domain id for Solana; its mint recipient must be a token account (the ATA).
  uint32 public constant SOLANA_CCTP_DOMAIN = 5;

  /// @dev Set for a destination chain, every `(tokenIn, tokenOut)` pair Circle's TokenMinterV2
  ///      registers for `cctpDomain` is routable there, with no per-pair configuration. Unset is
  ///      `minFinalityThreshold == 0` — `cctpDomain` can't be the sentinel, domain 0 is Ethereum.
  struct Domain {
    uint32 cctpDomain;
    uint32 minFinalityThreshold;
  }

  ICctpTokenMessengerV2 public immutable CCTP_TOKEN_MESSENGER;
  uint256 public nextOperationNonce;

  mapping(address tokenIn => mapping(uint256 dstChainId => Destination destination)) public destinations;
  mapping(uint256 dstChainId => Domain domain) public domains;

  event DomainSet(uint256 indexed _dstChainId, uint32 _cctpDomain, uint32 _minFinalityThreshold);
  event DomainCleared(uint256 indexed _dstChainId);
  event DestinationSet(
    address indexed _tokenIn,
    uint256 indexed _dstChainId,
    address indexed _tokenOut,
    uint32 _cctpDomain,
    uint32 _minFinalityThreshold
  );
  event DestinationCleared(address indexed _tokenIn, uint256 indexed _dstChainId);
  event SolanaAtaDestinationSet(
    address indexed _tokenIn,
    uint256 indexed _dstChainId,
    address indexed _tokenOut,
    bytes32 _solanaMint,
    bytes32 _solanaTokenProgram,
    bytes32 _solanaAssociatedTokenProgram
  );
  event CctpTransferStarted(
    bytes32 indexed _operationId,
    address indexed _inbox,
    address indexed _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    uint256 _maxFee,
    uint32 _cctpDomain,
    uint32 _minFinalityThreshold
  );

  error ZeroAddress();
  error InvalidAmount();
  error InvalidFeeBound();
  error InvalidRecipient();
  error InvalidSolanaAtaConfig();
  error UnsupportedDestination(address _tokenIn, uint256 _dstChainId);
  error InvalidTokenOut(address _expected, address _actual);
  error UnregisteredCctpToken(address _tokenIn, address _tokenOut, uint32 _cctpDomain);

  constructor(address _cctpTokenMessenger, address _owner) Ownable(_owner) {
    if (_cctpTokenMessenger == address(0)) {
      revert ZeroAddress();
    }

    CCTP_TOKEN_MESSENGER = ICctpTokenMessengerV2(_cctpTokenMessenger);
  }

  /// @notice Sets the CCTP domain and finality threshold for a destination chain. Any (tokenIn, tokenOut)
  ///         pair registered for that domain in Circle's TokenMinterV2 becomes routable.
  function setDomain(uint256 _dstChainId, uint32 _cctpDomain, uint32 _minFinalityThreshold) external onlyOwner {
    if (_dstChainId == 0 || _minFinalityThreshold == 0) {
      revert UnsupportedDestination(address(0), _dstChainId);
    }
    // A registry-derived corridor mints to the raw recipient; Solana mints to a token account (the ATA).
    if (_cctpDomain == SOLANA_CCTP_DOMAIN) {
      revert InvalidSolanaAtaConfig();
    }

    domains[_dstChainId] = Domain({cctpDomain: _cctpDomain, minFinalityThreshold: _minFinalityThreshold});

    emit DomainSet(_dstChainId, _cctpDomain, _minFinalityThreshold);
  }

  /// @notice Clears the CCTP domain config for a destination chain
  function clearDomain(uint256 _dstChainId) external onlyOwner {
    delete domains[_dstChainId];

    emit DomainCleared(_dstChainId);
  }

  /// @notice Sets a CCTP destination that mints to ATA(owner = logical recipient, mint = `_solanaMint`).
  /// @dev The ATA (and its canonical bump) is derived on-chain per recipient via `SolanaPda`.
  function setSolanaAtaDestination(
    address _tokenIn,
    uint256 _dstChainId,
    address _tokenOut,
    uint32 _cctpDomain,
    uint32 _minFinalityThreshold,
    bytes32 _solanaMint,
    bytes32 _solanaTokenProgram,
    bytes32 _solanaAssociatedTokenProgram
  ) external onlyOwner {
    if (_solanaMint == bytes32(0) || _solanaTokenProgram == bytes32(0) || _solanaAssociatedTokenProgram == bytes32(0)) {
      revert InvalidSolanaAtaConfig();
    }

    _setDestination(
      _tokenIn,
      _dstChainId,
      Destination({
        tokenOut: _tokenOut,
        cctpDomain: _cctpDomain,
        minFinalityThreshold: _minFinalityThreshold,
        solanaAta: SolanaAta({
          mint: _solanaMint, tokenProgram: _solanaTokenProgram, associatedTokenProgram: _solanaAssociatedTokenProgram
        })
      })
    );

    emit SolanaAtaDestinationSet(
      _tokenIn, _dstChainId, _tokenOut, _solanaMint, _solanaTokenProgram, _solanaAssociatedTokenProgram
    );
  }

  /// @dev Validation + storage for owner-configured destinations.
  function _setDestination(address _tokenIn, uint256 _dstChainId, Destination memory _destination) private {
    if (_dstChainId == 0) {
      revert UnsupportedDestination(_tokenIn, _dstChainId);
    }
    if (_tokenIn == address(0) || _destination.tokenOut == address(0)) {
      revert ZeroAddress();
    }
    // Solana mints to a token account, so it needs the ATA flavor; any other domain mints to the raw recipient.
    if ((_destination.cctpDomain == SOLANA_CCTP_DOMAIN) != (_destination.solanaAta.mint != bytes32(0))) {
      revert InvalidSolanaAtaConfig();
    }

    destinations[_tokenIn][_dstChainId] = _destination;
    _setBridgeRoute(_tokenIn, _destination.tokenOut, _dstChainId);

    emit DestinationSet(
      _tokenIn, _dstChainId, _destination.tokenOut, _destination.cctpDomain, _destination.minFinalityThreshold
    );
  }

  /// @notice Clears CCTP destination metadata for a destination chain
  function clearDestination(address _tokenIn, uint256 _dstChainId) external onlyOwner {
    delete destinations[_tokenIn][_dstChainId];
    _clearBridgeRoute(_tokenIn, _dstChainId);

    emit DestinationCleared(_tokenIn, _dstChainId);
  }

  /// @notice Returns the concrete CCTP mint recipient for a logical route recipient.
  function cctpMintRecipient(address _tokenIn, address _tokenOut, uint256 _dstChainId, bytes32 _recipient)
    external
    view
    returns (bytes32)
  {
    Destination memory destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    return _cctpMintRecipient(destination, _recipient);
  }

  /// @notice Quotes a CCTP burn for an explicit non-zero input amount.
  function quote(
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata
  ) external view override returns (BridgeQuote memory _quote) {
    _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    return _quoteBridgeAmount(_amountIn, _minAmountOut);
  }

  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata
  ) external override returns (BridgeExecution memory _execution) {
    Destination memory destination = _validatedDestination(_tokenIn, _tokenOut, _dstChainId, _recipient);
    uint256 amountIn = _resolveAmountIn(_amountIn, _inboxAssetBalance(_inbox, _tokenIn));
    BridgeQuote memory bridgeQuote = _quoteBridgeAmount(amountIn, _minAmountOut);

    uint256 maxFee = bridgeQuote.amountIn - bridgeQuote.amountOut;
    bytes32 recipient = _cctpMintRecipient(destination, _recipient);

    _execution.operationId =
      _nextOperationId(_inbox, _tokenIn, _tokenOut, _minAmountOut, _dstChainId, recipient, maxFee);
    _execution.quote = bridgeQuote;

    _setInboxTokenApproval(_inbox, _tokenIn, address(CCTP_TOKEN_MESSENGER), bridgeQuote.amountIn);

    _depositForBurn(
      _inbox,
      _tokenIn,
      bridgeQuote.amountIn,
      destination.cctpDomain,
      destination.minFinalityThreshold,
      recipient,
      maxFee
    );

    _setInboxTokenApproval(_inbox, _tokenIn, address(CCTP_TOKEN_MESSENGER), 0);

    emit CctpTransferStarted(
      _execution.operationId,
      _inbox,
      _tokenIn,
      _tokenOut,
      bridgeQuote.amountIn,
      _minAmountOut,
      _dstChainId,
      recipient,
      maxFee,
      destination.cctpDomain,
      destination.minFinalityThreshold
    );
  }

  function supportsBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId)
    public
    view
    override
    returns (bool)
  {
    // An explicit destination shadows the registry for its tokenIn, matching `_validatedDestination`.
    if (destinations[_tokenIn][_dstChainId].tokenOut != address(0)) {
      return super.supportsBridgeRoute(_tokenIn, _tokenOut, _dstChainId);
    }

    Domain memory domain = domains[_dstChainId];
    if (domain.minFinalityThreshold == 0) {
      return false;
    }

    address localToken = _cctpLocalToken(domain.cctpDomain, _tokenOut);
    return localToken != address(0) && localToken == _tokenIn;
  }

  function _validatedDestination(address _tokenIn, address _tokenOut, uint256 _dstChainId, bytes32 _recipient)
    private
    view
    returns (Destination memory destination)
  {
    destination = destinations[_tokenIn][_dstChainId];
    if (destination.tokenOut != address(0)) {
      if (_tokenOut != destination.tokenOut) {
        revert InvalidTokenOut(destination.tokenOut, _tokenOut);
      }
    } else {
      Domain memory domain = domains[_dstChainId];
      if (domain.minFinalityThreshold == 0) {
        revert UnsupportedDestination(_tokenIn, _dstChainId);
      }
      address localToken = _cctpLocalToken(domain.cctpDomain, _tokenOut);
      if (localToken == address(0) || localToken != _tokenIn) {
        revert UnregisteredCctpToken(_tokenIn, _tokenOut, domain.cctpDomain);
      }
      destination.tokenOut = _tokenOut;
      destination.cctpDomain = domain.cctpDomain;
      destination.minFinalityThreshold = domain.minFinalityThreshold;
    }
    if (_recipient == bytes32(0)) {
      revert InvalidRecipient();
    }
  }

  /// @dev Reads `localMinter()` live because Circle can rotate it.
  function _cctpLocalToken(uint32 _cctpDomain, address _remoteToken) private view returns (address) {
    return
      ICctpTokenMinterV2(CCTP_TOKEN_MESSENGER.localMinter()).getLocalToken(_cctpDomain, _addressToBytes32(_remoteToken));
  }

  function _quoteBridgeAmount(uint256 _amountIn, uint256 _minAmountOut)
    private
    pure
    returns (BridgeQuote memory _quote)
  {
    if (_amountIn == 0) {
      revert InvalidAmount();
    }

    if (_minAmountOut == 0 || _minAmountOut > _amountIn) {
      revert InvalidFeeBound();
    }

    BridgeFee[] memory fees = new BridgeFee[](0);

    _quote = BridgeQuote({amountIn: _amountIn, amountOut: _minAmountOut, fees: fees});
  }

  function _cctpMintRecipient(Destination memory _destination, bytes32 _recipient) private view returns (bytes32) {
    SolanaAta memory solanaAta = _destination.solanaAta;
    if (solanaAta.mint == bytes32(0)) {
      return _recipient; // raw passthrough
    }

    (bytes32 ata,) = SolanaPda.findAssociatedTokenAccount(
      _recipient, solanaAta.tokenProgram, solanaAta.mint, solanaAta.associatedTokenProgram
    );
    return ata;
  }

  function _depositForBurn(
    address _inbox,
    address _tokenIn,
    uint256 _amountIn,
    uint32 _cctpDomain,
    uint32 _minFinalityThreshold,
    bytes32 _recipient,
    uint256 _maxFee
  ) internal {
    _executeInboxTransaction(
      _inbox,
      address(CCTP_TOKEN_MESSENGER),
      0,
      abi.encodeCall(
        ICctpTokenMessengerV2.depositForBurn,
        (_amountIn, _cctpDomain, _recipient, _tokenIn, bytes32(0), _maxFee, _minFinalityThreshold)
      )
    );
  }

  function _nextOperationId(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    uint256 _maxFee
  ) internal returns (bytes32) {
    uint256 nonce = nextOperationNonce++;
    return keccak256(
      abi.encode(
        block.chainid,
        address(this),
        nonce,
        msg.sender,
        _inbox,
        _tokenIn,
        _tokenOut,
        _minAmountOut,
        _dstChainId,
        _recipient,
        _maxFee
      )
    );
  }
}

