// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

struct BridgeFee {
  address token;
  uint256 amount;
}

struct BridgeQuote {
  uint256 amountIn;
  uint256 amountOut;
  BridgeFee[] fees;
}

struct BridgeExecution {
  bytes32 operationId;
  BridgeQuote quote;
}

/// @title IBridgeAdapter
/// @author Agustin Aguilar
/// @notice Interface for adapters that bridge assets from an inbox
interface IBridgeAdapter {
  /// @notice Returns whether the exact input token, output token, and destination chain route is supported.
  function supportsBridgeRoute(address _tokenIn, address _tokenOut, uint256 _dstChainId)
    external
    view
    returns (bool _supported);

  /// @notice Quotes a bridge operation for an explicit non-zero input amount.
  function quote(
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata _adapterCalldata
  ) external view returns (BridgeQuote memory _quote);

  /// @notice Executes a bridge operation from `_inbox`; `_amountIn == 0` uses the full inbox balance.
  function execute(
    address _inbox,
    address _tokenIn,
    address _tokenOut,
    uint256 _amountIn,
    uint256 _minAmountOut,
    uint256 _dstChainId,
    bytes32 _recipient,
    bytes calldata _adapterCalldata
  ) external returns (BridgeExecution memory _execution);
}

