pragma solidity ^0.8.26;

/// @title ICctpTokenMessengerV2
/// @author Agustin Aguilar
/// @notice Minimal CCTP TokenMessenger v2 interface
interface ICctpTokenMessengerV2 {
  function depositForBurn(
    uint256 _amount,
    uint32 _destinationDomain,
    bytes32 _mintRecipient,
    address _burnToken,
    bytes32 _destinationCaller,
    uint256 _maxFee,
    uint32 _minFinalityThreshold
  ) external;

  function localMinter() external view returns (address);
}

/// @title ICctpTokenMinterV2
/// @notice Minimal CCTP TokenMinter v2 interface
interface ICctpTokenMinterV2 {
  function getLocalToken(uint32 _remoteDomain, bytes32 _remoteToken) external view returns (address);
}

