pragma solidity ^0.8.26;

/// @title SolanaPda
/// @notice On-chain (EVM) replica of Solana's `find_program_address` / `create_program_address`.
/// @dev Solana derives a Program Derived Address by hashing the seeds, a bump byte, the program id
///      and the marker `"ProgramDerivedAddress"`, then requiring the result to be OFF the ed25519
///      curve (so no private key can exist for it). `find_program_address` walks the bump from 255
///      downward and returns the first off-curve candidate (the "canonical" bump).
///
///      The only non-trivial part on EVM is the off-curve test. A 32-byte value is a valid ed25519
///      point iff, interpreting the low 255 bits as the little-endian `y` coordinate, the value
///      `x^2 = (y^2 - 1) / (d*y^2 + 1)` is a quadratic residue in F_p (p = 2^255 - 19). We avoid a
///      modular inverse by using the identity QR(u/v) == QR(u*v) for v != 0 (they differ by the
///      square factor v^2), so a single Legendre symbol via the MODEXP precompile decides curve
///      membership. This matches curve25519-dalek's `CompressedEdwardsY::decompress().is_some()`,
///      which Solana uses for `bytes_are_curve_point`.
library SolanaPda {
  /// @dev Field prime p = 2^255 - 19.
  uint256 internal constant P = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffed;
  /// @dev Edwards curve constant d = -121665/121666 mod p.
  uint256 internal constant D = 0x52036cee2b6ffe738cc740797779e89800700a4d4141d8ab75eb4dca135978a3;
  /// @dev (p - 1) / 2, the Legendre symbol exponent.
  uint256 internal constant P_MINUS_1_DIV_2 = 0x3ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff6;
  /// @dev Low 255 bits; clears the ed25519 x-coordinate sign bit.
  uint256 internal constant MASK_255 = 0x7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff;
  /// @dev Trailing marker appended to every PDA preimage.
  bytes internal constant PDA_MARKER = "ProgramDerivedAddress";

  error NoCanonicalBump();

  /// @notice Returns true if `point` (raw 32 hashed bytes, little-endian ed25519 encoding) lies on
  ///         the ed25519 curve. On-curve points are NOT valid PDAs.
  function isOnCurve(bytes32 point) internal view returns (bool) {
    // Reverse to a little-endian integer and drop the sign bit -> y coordinate.
    uint256 y = _reverseBytes(point) & MASK_255;

    uint256 yy = mulmod(y, y, P);
    uint256 u = addmod(yy, P - 1, P); // y^2 - 1
    uint256 v = addmod(mulmod(D, yy, P), 1, P); // d*y^2 + 1

    if (v == 0) {
      return false; // no x exists -> off curve
    }

    uint256 uv = mulmod(u, v, P);
    if (uv == 0) {
      return true; // u == 0 -> x = 0, on curve (y = +/-1)
    }

    // Legendre symbol of u*v: 1 => quadratic residue (on curve), p-1 => non-residue (off curve).
    return _modexp(uv, P_MINUS_1_DIV_2, P) == 1;
  }

  /// @notice EVM equivalent of `create_program_address`: hash a fixed bump into the seeds.
  /// @param seeds The seed bytes concatenated (Solana hashes seeds back-to-back, no separators).
  /// @param bump  The bump seed byte.
  /// @param programId The owning program id (raw 32 bytes).
  /// @return ok  False when the derived address is on-curve (an invalid PDA).
  /// @return pda The derived address.
  function createProgramAddress(bytes memory seeds, uint8 bump, bytes32 programId)
    internal
    view
    returns (bool ok, bytes32 pda)
  {
    pda = sha256(abi.encodePacked(seeds, bump, programId, PDA_MARKER));
    ok = !isOnCurve(pda);
  }

  /// @notice EVM equivalent of `find_program_address`: walk bumps 255->0, return the first
  ///         off-curve (canonical) address. Reverts if none exists (cryptographically impossible).
  /// @dev The preimage `seeds||bump||programId||marker` is built once; each iteration only rewrites
  ///      the single bump byte in place and re-hashes via the sha256 precompile, avoiding a fresh
  ///      `abi.encodePacked` allocation+copy per step.
  function findProgramAddress(bytes memory seeds, bytes32 programId) internal view returns (bytes32 pda, uint8 bump) {
    bytes memory preimage = abi.encodePacked(seeds, uint8(0), programId, PDA_MARKER);
    uint256 bumpOffset = seeds.length; // byte index of the bump within the preimage payload

    for (uint256 b = 255;;) {
      bytes32 candidate = _sha256WithBump(preimage, bumpOffset, b);
      if (!isOnCurve(candidate)) {
        return (candidate, uint8(b));
      }
      if (b == 0) break;
      unchecked {
        --b;
      }
    }
    revert NoCanonicalBump();
  }

  /// @notice Canonical Associated Token Account for `(owner, tokenProgram, mint)`, derived in full
  ///         on-chain (no precomputed bump required).
  function findAssociatedTokenAccount(bytes32 owner, bytes32 tokenProgram, bytes32 mint, bytes32 associatedTokenProgram)
    internal
    view
    returns (bytes32 ata, uint8 bump)
  {
    return findProgramAddress(abi.encodePacked(owner, tokenProgram, mint), associatedTokenProgram);
  }

  /// @dev Reverse the byte order of a bytes32 (big-endian word <-> little-endian word).
  function _reverseBytes(bytes32 input) private pure returns (uint256 v) {
    v = uint256(input);
    v = ((v & 0xFF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00) >> 8)
      | ((v & 0x00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF00FF) << 8);
    v = ((v & 0xFFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000) >> 16)
      | ((v & 0x0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF0000FFFF) << 16);
    v = ((v & 0xFFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000) >> 32)
      | ((v & 0x00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF00000000FFFFFFFF) << 32);
    v = ((v & 0xFFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF0000000000000000) >> 64)
      | ((v & 0x0000000000000000FFFFFFFFFFFFFFFF0000000000000000FFFFFFFFFFFFFFFF) << 64);
    v = (v >> 128) | (v << 128);
  }

  /// @dev Write `bump` into `preimage` at `bumpOffset`, then sha256 it via the 0x02 precompile.
  function _sha256WithBump(bytes memory preimage, uint256 bumpOffset, uint256 bump) private view returns (bytes32 out) {
    assembly ("memory-safe") {
      let dataPtr := add(preimage, 0x20)
      mstore8(add(dataPtr, bumpOffset), bump)
      if iszero(staticcall(gas(), 0x02, dataPtr, mload(preimage), 0x00, 0x20)) { revert(0, 0) }
      out := mload(0x00)
    }
  }

  /// @dev modexp via the 0x05 precompile for 32-byte base/exponent/modulus operands.
  function _modexp(uint256 base, uint256 exponent, uint256 modulus) private view returns (uint256 result) {
    assembly ("memory-safe") {
      let ptr := mload(0x40)
      mstore(ptr, 0x20) // base length
      mstore(add(ptr, 0x20), 0x20) // exponent length
      mstore(add(ptr, 0x40), 0x20) // modulus length
      mstore(add(ptr, 0x60), base)
      mstore(add(ptr, 0x80), exponent)
      mstore(add(ptr, 0xa0), modulus)
      if iszero(staticcall(gas(), 0x05, ptr, 0xc0, 0x00, 0x20)) { revert(0, 0) }
      result := mload(0x00)
    }
  }
}

